"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  AlertTriangle, ArrowRight, Check, ChevronRight, CircleDot, Clock3, FileCheck2, FlaskConical,
  GitBranch, GitCompare, LayoutDashboard, Link2, LoaderCircle, LogOut, Plus, RefreshCcw, Search, ShieldCheck, Sparkles, Video, XCircle,
} from "lucide-react";
import type { WorkflowAction } from "@/domain/actions";
import type { BuildProject, Channel, VideoProject } from "@/domain/entities";
import type { ReferenceReportSection } from "@/domain/studio-contracts";
import type { MediaProductionSnapshot } from "@/domain/media-production";
import { ChannelResearchWorkspace, type WorkflowList } from "./channel-research-workspace";
import { ChannelStrategyWorkspace } from "./channel-strategy-workspace";

type ApiSnapshot = { channels: Channel[]; videos: VideoProject[]; buildProjects: BuildProject[]; products: Array<{ id: string }>; agentRuns: Array<{ id: string; agent: string; status: string; costUsd: number; fixture?: boolean; provider?: string; startedAt: string }>; auditEvents: Array<{ id: string; type: string; entityId?: string; at: string }>; conversationMessages: Array<{ id: string; channelId: string; role: "USER" | "SYSTEM"; content: string; targetType: string; createdAt: string }>; mediaProduction: MediaProductionSnapshot; workflowEngine?: WorkflowList };

const channelStages = ["CONCEPT", "EVIDENCE", "DECISION", "STRATEGY", "READY"];
const scoreLabels: Record<string, string> = {
  audienceDemand: "Audience demand", competition: "Competition position", monetization: "Monetization",
  contentDepth: "Content depth", productionFeasibility: "Production feasibility",
  differentiationPotential: "Differentiation", trendStability: "Trend stability",
};

const key = () => crypto.randomUUID();

export default function StudioApp({ user }: { user: { email: string; mode: "mock" | "supabase" } }) {
  const [snapshot, setSnapshot] = useState<ApiSnapshot | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [showNew, setShowNew] = useState(false);

  useEffect(() => {
    let active = true;
    fetch("/api/workflows", { cache: "no-store" })
      .then(async (response) => {
        const data = await response.json();
        if (!response.ok) throw new Error(data.error ?? "Could not load workspace");
        if (active) setSnapshot(data);
      })
      .catch((cause: unknown) => { if (active) setError(cause instanceof Error ? cause.message : "Could not load workspace"); });
    return () => { active = false; };
  }, []);

  const act = async (action: WorkflowAction, success: string) => {
    setBusy(true); setError(null); setNotice(null);
    try {
      const response = await fetch("/api/workflows", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": key() }, body: JSON.stringify(action) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error ?? "The workflow did not advance");
      setSnapshot(data); setNotice(success); setShowNew(false);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "The workflow did not advance"); }
    finally { setBusy(false); }
  };

  const activeChannel = snapshot?.channels.at(-1);
  const activeVideo = activeChannel ? snapshot?.videos.filter((video) => video.channelId === activeChannel.id).at(-1) : undefined;
  const activeBuild = activeChannel ? snapshot?.buildProjects.filter((project) => project.channelId === activeChannel.id).at(-1) : undefined;

  return (
    <div className="studio-shell">
      <aside className="studio-sidebar">
        <Link className="wordmark" href="/"><span>CW</span> CHANNELWRIGHT</Link>
        <nav aria-label="Studio"><a className="active" href="#workspace"><LayoutDashboard size={17} /> Workspace</a><a href="#channels"><GitBranch size={17} /> Channels <b>{snapshot?.channels.length ?? 0}</b></a><a href="#videos"><Video size={17} /> Videos <b>{snapshot?.videos.length ?? 0}</b></a><a href="#offers"><CircleDot size={17} /> Offers <b>{snapshot?.channels.reduce((sum, channel) => sum + channel.offerSelections.length, 0) ?? 0}</b></a><a href="#products"><ShieldCheck size={17} /> Products <b>{snapshot?.products.length ?? 0}</b></a><a href="#funnels"><Link2 size={17} /> Funnels <b>{snapshot?.buildProjects.filter((item) => item.projectType === "FREE_RESOURCE").length ?? 0}</b></a><a href="#monetization"><Sparkles size={17} /> Monetization <b>{snapshot?.channels.reduce((sum, channel) => sum + channel.monetizationPlans.length, 0) ?? 0}</b></a><a href="#runs"><CircleDot size={17} /> Agent runs <b>{snapshot?.agentRuns.length ?? 0}</b></a></nav>
        <div className="sidebar-bottom"><div className="mode-chip"><FlaskConical size={14} /> {user.mode === "mock" ? "FIXTURE MODE" : "SUPABASE AUTH"}</div><div className="user-row"><span>{user.email.slice(0, 1).toUpperCase()}</span><div><strong>{user.email}</strong><small>Studio operator</small></div></div><form action="/api/auth/logout" method="post"><button className="sidebar-logout"><LogOut size={15} /> Sign out</button></form></div>
      </aside>

      <main id="main" className="studio-main">
        <header className="studio-header"><div><p className="eyebrow">Production control</p><h1>Channel workspace</h1></div><button className="button" onClick={() => setShowNew(true)}><Plus size={16} /> New channel</button></header>
        {error && <div className="error-banner" role="alert"><AlertTriangle size={17} /> {error}<button onClick={() => setError(null)}>×</button></div>}
        {notice && <div className="success-banner" role="status"><Check size={17} /> {notice}<button onClick={() => setNotice(null)}>×</button></div>}
        {busy && <div className="working-bar" role="status"><LoaderCircle className="spin" size={15} /> Validating output and advancing workflow…</div>}

        {!snapshot ? <LoadingState /> : user.mode === "supabase" && !activeChannel ? <><ChannelResearchWorkspace initial={snapshot.workflowEngine} media={snapshot.mediaProduction} /><ChannelStrategyWorkspace initial={snapshot.workflowEngine} /></> : showNew || !activeChannel ? <NewChannelForm busy={busy} onSubmit={act} /> : (
          <div id="workspace" className="workspace-grid">
            <section className="conversation-pane"><ConversationWorkspace snapshot={snapshot} channel={activeChannel} video={activeVideo} build={activeBuild} busy={busy} act={act} /><ActivityRail snapshot={snapshot} channel={activeChannel} /></section>
            <section className="workspace-primary artifact-workspace" aria-label="Artifact workspace">
              <ChannelOverview channel={activeChannel} />
              {activeChannel.state === "CONCEPT_REVIEW_REQUIRED" && <ViabilityReview channel={activeChannel} busy={busy} act={act} />}
              {activeChannel.state === "CONCEPT_SELECTION_REQUIRED" && <ConceptSelection channel={activeChannel} busy={busy} act={act} />}
              {activeChannel.state === "REFERENCE_CHANNEL_REVIEW_REQUIRED" && <ReferenceResearchReview channel={activeChannel} busy={busy} act={act} />}
              {activeChannel.state === "FAILED" && activeChannel.mode === "REFERENCE_CHANNEL" && <ReferenceResearchFailure channel={activeChannel} busy={busy} act={act} />}
              {activeChannel.state === "BUSINESS_STRATEGY_REVIEW_REQUIRED" && <BusinessStrategyReview channel={activeChannel} busy={busy} act={act} />}
              {activeChannel.state === "READY_FOR_VIDEO_PRODUCTION" && (activeChannel.monetizationPlans.at(-1)?.status === "REVIEW_REQUIRED" ? <MonetizationReview channel={activeChannel} busy={busy} act={act} /> : <ReadyWorkspace channel={activeChannel} video={activeVideo} build={activeBuild} media={snapshot.mediaProduction} busy={busy} act={act} />)}
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

function ConversationWorkspace({ snapshot, channel, video, build, busy, act }: { snapshot: ApiSnapshot; channel: Channel; video?: VideoProject; build?: BuildProject; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const [message, setMessage] = useState("");
  const recent = [
    ...snapshot.conversationMessages.filter((item) => item.channelId === channel.id).map((item) => ({ id: item.id, at: item.createdAt, kind: item.role, title: `Change request · ${item.targetType.replaceAll("_", " ")}`, detail: item.content })),
    ...snapshot.auditEvents.map((item) => ({ id: item.id, at: item.at, kind: "DECISION", title: item.type.replaceAll("_", " "), detail: "Recorded in the owner-scoped audit ledger" })),
    ...snapshot.agentRuns.map((item) => ({ id: item.id, at: item.startedAt, kind: item.fixture === false ? "LIVE AGENT" : "FIXTURE AGENT", title: item.agent.replaceAll("_", " "), detail: `${item.status} · ${item.provider ?? "deterministic fixture"} · $${item.costUsd.toFixed(2)}` })),
  ].sort((a, b) => b.at.localeCompare(a.at)).slice(0, 10);
  const target = channel.state === "REFERENCE_CHANNEL_REVIEW_REQUIRED" ? "REFERENCE_REPORT"
    : channel.state === "BUSINESS_STRATEGY_REVIEW_REQUIRED" ? "BUSINESS_STRATEGY"
      : channel.monetizationPlans.at(-1)?.status === "REVIEW_REQUIRED" ? "MONETIZATION_PLAN"
        : build?.state === "SPEC_REVIEW" ? "BUILD_SPECIFICATION"
          : build?.state === "USER_REVIEW" ? "BUILD_ARTIFACT"
            : video?.state === "SCRIPT_REVIEW_REQUIRED" ? "SCRIPT" : null;
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!target || !message.trim()) return;
    if (target === "REFERENCE_REPORT") void act({ type: "REVISE_REFERENCE_REPORT", channelId: channel.id, reportVersion: channel.referenceReports.at(-1)!.version, section: "ORIGINAL_CONCEPT", instructions: message, source: "CONVERSATION" }, "Conversation request created a new reference-report version.");
    else if (target === "BUSINESS_STRATEGY") void act({ type: "BUSINESS_STRATEGY_DECISION", channelId: channel.id, strategyVersion: channel.businessStrategies.at(-1)!.version, decision: "REQUEST_CHANGES", feedback: message, source: "CONVERSATION" }, "Conversation request created a new strategy version.");
    else if (target === "MONETIZATION_PLAN") void act({ type: "MONETIZATION_PLAN_DECISION", channelId: channel.id, planVersion: channel.monetizationPlans.at(-1)!.version, decision: "REQUEST_CHANGES", feedback: message, source: "CONVERSATION" }, "Conversation request created a new monetization-plan version.");
    else if (target === "BUILD_SPECIFICATION") void act({ type: "BUILD_SPEC_DECISION", buildProjectId: build!.id, specificationVersion: build!.specifications.at(-1)!.version, decision: "REQUEST_CHANGES", feedback: message, source: "CONVERSATION" }, "Conversation request created a new build specification version.");
    else if (target === "BUILD_ARTIFACT") void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: build!.id, artifactVersion: build!.artifacts.at(-1)!.version, decision: "REQUEST_CHANGES", feedback: message, source: "CONVERSATION" }, "Conversation request created a new build artifact version.");
    else void act({ type: "SCRIPT_DECISION", videoId: video!.id, decision: "REQUEST_CHANGES", feedback: message, source: "CONVERSATION" }, "Conversation request created a new script version.");
    setMessage("");
  };
  return <section className="conversation-workspace"><header><p className="eyebrow">Conversation and activity</p><h2>Direct the work</h2><span>{target ? `REVISING ${target.replaceAll("_", " ")}` : "NO ARTIFACT AWAITING CHANGES"}</span></header><div className="conversation-stream">{recent.map((item) => <article key={`${item.kind}-${item.id}`}><i /><div><small>{item.kind} · {new Date(item.at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</small><strong>{item.title}</strong><p>{item.detail}</p></div></article>)}</div><form className="prompt-composer" onSubmit={submit}><label htmlFor="studio-prompt">Request a change</label><textarea id="studio-prompt" rows={4} maxLength={4000} value={message} onChange={(event) => setMessage(event.target.value)} disabled={!target || busy} placeholder={target ? "Describe the change. Channelwright will create a new typed version." : "Open an artifact that is waiting for review to request changes."} /><div><small>Approved artifacts are never overwritten.</small><button className="button button-accent" disabled={!target || busy || !message.trim()}>Create new version <ArrowRight size={14} /></button></div></form></section>;
}

function LoadingState() { return <div className="loading-state"><LoaderCircle className="spin" /><p>Opening the production ledger…</p></div>; }

export function ProductionCapabilityBoundary({ media }: { media: MediaProductionSnapshot }) {
  return <section className="production-capability"><p className="eyebrow">Supabase production boundary</p><h2>Transactional media production is enabled</h2><p>Planning-agent mutations remain capability-specific HTTP 501 responses. Existing approved database scripts can be queued through the media action API; publishing, OAuth, and provider generation are not enabled.</p><div><span>{media.assets.length}<b>ASSET VERSIONS</b></span><span>{media.renderJobs.length}<b>RENDER JOBS</b></span><span>{media.masters.length}<b>MASTER VERSIONS</b></span></div><small>DATABASE EVIDENCE ONLY · DEPLOYED WORKER AND DURABLE STORAGE EXECUTION NOT YET VERIFIED</small></section>;
}

export function NewChannelForm({ busy, onSubmit }: { busy: boolean; onSubmit: (action: WorkflowAction, success: string) => Promise<void> }) {
  const [mode, setMode] = useState<"USER_DEFINED" | "AGENT_DISCOVERED" | "REFERENCE_CHANNEL">("USER_DEFINED");
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    void onSubmit({
      type: "CREATE_CHANNEL", mode,
      concept: mode === "USER_DEFINED" ? String(form.get("concept")) : undefined,
      referenceChannel: mode === "REFERENCE_CHANNEL" ? {
        url: String(form.get("referenceUrl")),
        likedAspects: String(form.get("likedAspects") || "") || undefined,
        restrictions: String(form.get("restrictions") || "") || undefined,
      } : undefined,
      preferences: {
        name: String(form.get("name")), niche: String(form.get("niche")), targetAudience: String(form.get("targetAudience")),
        videoStyle: String(form.get("videoStyle")), preferredVoice: String(form.get("preferredVoice")),
        targetDurationMinutes: Number(form.get("duration")), postingFrequency: String(form.get("frequency")),
        monetizationGoal: String(form.get("monetization")), language: String(form.get("language")), productionComplexity: String(form.get("complexity")) as "LEAN" | "BALANCED" | "PREMIUM",
        distributionTargets: {
          youtube: true,
          tiktok: form.has("tiktok"),
          instagramFacebookReels: form.has("instagramFacebookReels"),
        },
      },
    }, mode === "USER_DEFINED" ? "Concept evaluated and workflow advanced." : mode === "AGENT_DISCOVERED" ? "Three evaluated concept directions are ready." : "Reference source resolved and fixture report created for review.");
  };
  return <section className="form-panel reveal"><div className="panel-kicker"><span>01</span><div><p className="eyebrow">Channel onboarding</p><h2>Set the editorial brief</h2></div></div><p className="panel-lede">Start with your own thesis, discover opportunities, or use an established channel as market inspiration. Reference mode always produces an original direction and records what must not be copied.</p>
    <form onSubmit={submit} className="channel-form">
      <fieldset><legend>How should this channel begin?</legend><div className="mode-cards"><button type="button" className={mode === "USER_DEFINED" ? "selected" : ""} onClick={() => setMode("USER_DEFINED")}><span><GitBranch size={20} /></span><strong>I have a concept</strong><small>Research and evaluate my exact idea.</small><i>{mode === "USER_DEFINED" && <Check size={13} />}</i></button><button type="button" className={mode === "AGENT_DISCOVERED" ? "selected" : ""} onClick={() => setMode("AGENT_DISCOVERED")}><span><Sparkles size={20} /></span><strong>Discover opportunities</strong><small>Generate and score several distinct directions.</small><i>{mode === "AGENT_DISCOVERED" && <Check size={13} />}</i></button><button type="button" className={mode === "REFERENCE_CHANNEL" ? "selected" : ""} onClick={() => setMode("REFERENCE_CHANNEL")}><span><Link2 size={20} /></span><strong>Use a reference channel</strong><small>Research market inspiration and build an original position.</small><i>{mode === "REFERENCE_CHANNEL" && <Check size={13} />}</i></button></div></fieldset>
      <div className="field-grid"><label>Channel name<input name="name" required minLength={2} defaultValue="Systems, Explained" /></label><label>Niche<input name="niche" required minLength={2} defaultValue="Business and technology" /></label></div>
      {mode === "USER_DEFINED" && <label>Channel concept<textarea name="concept" required minLength={10} rows={3} defaultValue="Visual breakdowns of the hidden systems behind everyday businesses" /><small>Try “Daily AI News” for STOP or “Failed Startup Autopsies” for CAUTION in fixture mode.</small></label>}
      {mode === "REFERENCE_CHANNEL" && <section className="reference-inputs"><label>YouTube channel URL<input name="referenceUrl" type="url" required maxLength={500} placeholder="https://www.youtube.com/@channel" /></label><label>What do you value about it? <small>Optional</small><textarea name="likedAspects" rows={3} maxLength={1000} placeholder="Topic clarity, teaching depth, audience focus…" /></label><label>What must not be imitated? <small>Optional</small><textarea name="restrictions" rows={3} maxLength={1000} placeholder="Names, visual devices, content structures, or other restrictions" /></label><p><ShieldCheck size={16} /> The reference is market input only. Channelwright creates an original name, identity, editorial system, resources, products, and pages.</p></section>}
      <div className="field-grid"><label>Target audience<input name="targetAudience" defaultValue="Curious independent founders" /></label><label>Language<input name="language" defaultValue="English" /></label><label>Video style<input name="videoStyle" defaultValue="Editorial visual documentary" /></label><label>Preferred voice<input name="preferredVoice" defaultValue="Measured and incisive" /></label><label>Production complexity<select name="complexity" defaultValue="BALANCED"><option value="LEAN">Lean</option><option value="BALANCED">Balanced</option><option value="PREMIUM">Premium</option></select></label><label>Target length<select name="duration" defaultValue="10"><option value="6">6 minutes</option><option value="10">10 minutes</option><option value="15">15 minutes</option><option value="25">25 minutes</option></select></label><label>Posting frequency<select name="frequency" defaultValue="Weekly"><option>Twice weekly</option><option>Weekly</option><option>Every two weeks</option></select></label><label>Monetization goal<input name="monetization" defaultValue="Sponsorships and aligned affiliates" /></label></div>
      <DistributionTargetControls />
      <button className="button button-accent button-wide" disabled={busy} type="submit">{mode === "USER_DEFINED" ? "Research my concept" : mode === "AGENT_DISCOVERED" ? "Find channel concepts" : "Research reference and propose an original direction"}<ArrowRight size={17} /></button>
    </form></section>;
}

export function DistributionTargetControls() {
  return <fieldset className="distribution-fieldset"><legend>Platform optimization</legend><p>Every video starts with the canonical YouTube production. Selected vertical adaptations begin only after the approved source is available.</p><div className="distribution-options">
    <label className="distribution-option locked"><input type="checkbox" checked disabled aria-describedby="youtube-description" /><span><strong>YouTube <small>REQUIRED</small></strong><em id="youtube-description">Canonical long-form video and publishing package.</em></span><b aria-hidden="true">LOCKED</b></label>
    <label className="distribution-option"><input type="checkbox" name="tiktok" /><span><strong>TikTok</strong><em>Generate a rapid, standalone vertical adaptation plan after the YouTube source is approved.</em></span></label>
    <label className="distribution-option"><input type="checkbox" name="instagramFacebookReels" /><span><strong>Instagram/Facebook Reels</strong><em>Generate one Reels-compatible media plan with destination-aware Instagram and Facebook copy.</em></span></label>
  </div></fieldset>;
}

function ReferenceResearchFailure({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  return <section className="reference-failure" role="alert"><XCircle size={28} /><div><p className="eyebrow">Reference provider blocked</p><h2>The channel could not be resolved or researched.</h2><p>The failure is recorded in the activity ledger. Check the supported YouTube URL or provider configuration, then retry without creating a duplicate channel.</p></div><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "RETRY_REFERENCE_RESEARCH", channelId: channel.id }, "Reference research retried.")}>Retry research <RefreshCcw size={15} /></button></section>;
}

function ReferenceResearchReview({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const latest = channel.referenceReports.at(-1)!;
  const [compareVersion, setCompareVersion] = useState(latest.version > 1 ? latest.version - 1 : latest.version);
  const [revising, setRevising] = useState(false);
  const [section, setSection] = useState<ReferenceReportSection>("DIFFERENTIATION");
  const [instructions, setInstructions] = useState("");
  const compared = channel.referenceReports.find((item) => item.version === compareVersion) ?? latest;
  const report = latest.report;
  const source = channel.referenceSource!;
  const revise = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    void act({ type: "REVISE_REFERENCE_REPORT", channelId: channel.id, reportVersion: latest.version, section, instructions }, `Reference report v${latest.version + 1} created and independently reviewed.`);
  };
  const switchToConcept = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    void act({ type: "REFERENCE_REPORT_DECISION", channelId: channel.id, reportVersion: latest.version, decision: "SWITCH_TO_USER_DEFINED", concept: String(form.get("concept")), niche: String(form.get("niche")) }, "Reference direction rejected; your concept was evaluated instead.");
  };
  return <section className="reference-report">
    <header className="reference-report-head"><div><p className="eyebrow">Reference research / Version {latest.version}</p><h2>An original direction, with the evidence boundary visible.</h2><p>{report.proposedOriginalConcept.positioning}</p></div><div className={`provenance-stamp ${report.fixture ? "fixture" : "live"}`}><span>{report.fixture ? "FIXTURE" : "LIVE"}</span><strong>{latest.qa.verdict}</strong><small>{source.provider}</small></div></header>
    <div className="source-tape"><div><Link2 size={17} /><span><small>REFERENCE SOURCE</small><a href={source.canonicalUrl} target="_blank" rel="noreferrer">{source.title}</a></span></div><div><small>STABLE ID</small><code>{source.stableChannelId}</code></div><div><small>ACCESSED</small><time>{new Date(source.resolvedAt).toLocaleString()}</time></div></div>
    {report.incompleteDataWarnings.map((warning) => <div className="evidence-warning" key={warning}><AlertTriangle size={16} /><p><strong>Incomplete evidence</strong>{warning}</p></div>)}
    <div className="reference-report-grid">
      <article className="report-main"><section><p className="eyebrow">Public positioning</p><h3>{report.publiclyObservablePositioning}</h3><p>{report.likelyAudience.description}</p><div className="tag-list">{report.contentClusters.map((item) => <span key={item}>{item}</span>)}</div></section><section><p className="eyebrow">Original differentiation</p>{report.originalDifferentiationRecommendations.map((item) => <p className="ledger-item" key={item}><Check size={14} />{item}</p>)}</section><section><p className="eyebrow">What Channelwright must not copy</p>{report.mustNotCopy.map((item) => <p className="ledger-item danger" key={item}><XCircle size={14} />{item}</p>)}</section></article>
      <aside className="report-candidates"><CandidateList title="Pillar Video candidates" items={report.pillarVideoCandidates} /><CandidateList title="Free resource candidates" items={report.freeResourceCandidates} /><CandidateList title="Paid product candidates" items={report.paidProductCandidates} /></aside>
    </div>
    <section className="report-details"><details><summary>Evidence, contradictions, and unknowns</summary><div className="detail-columns"><article><h3>Sources</h3>{report.dataSources.map((item) => <p key={item.sourceId}><b>{item.confidence}</b> {item.title}<small>{item.fixture ? "Fixture source" : item.provider}</small></p>)}</article><article><h3>Unknowns</h3>{report.unknowns.map((item) => <p key={item}>{item}</p>)}<h3>Contradictions</h3>{report.contradictions.map((item) => <p key={item}>{item}</p>)}</article></div></details></section>
    <section className="version-compare"><div><GitCompare size={17} /><span><strong>Compare versions</strong><small>Approved artifacts are never overwritten.</small></span></div><label>Compare latest with<select value={compareVersion} onChange={(event) => setCompareVersion(Number(event.target.value))}>{channel.referenceReports.map((item) => <option value={item.version} key={item.id}>Version {item.version}</option>)}</select></label>{compared.version !== latest.version && <article><span>v{compared.version}</span><p>{compared.report.proposedOriginalConcept.valueProposition}</p><small>{latest.changeInstructions ?? "No recorded change instruction"}</small></article>}</section>
    {revising && <form className="revision-form" onSubmit={revise}><h3>Create report version {latest.version + 1}</h3><label>Section<select value={section} onChange={(event) => setSection(event.target.value as ReferenceReportSection)}>{["POSITIONING", "AUDIENCE", "TOPICS", "PATTERNS", "DEMAND", "MONETIZATION", "DIFFERENTIATION", "ORIGINAL_CONCEPT", "BRAND", "PILLAR_VIDEOS", "FREE_RESOURCES", "PAID_PRODUCTS", "REVENUE_STREAMS"].map((item) => <option key={item}>{item}</option>)}</select></label><label>Change instruction<textarea required minLength={3} maxLength={4000} rows={4} value={instructions} onChange={(event) => setInstructions(event.target.value)} placeholder="State what should change and why." /></label><div className="button-row"><button className="button button-accent" disabled={busy}>Create new version <RefreshCcw size={15} /></button><button type="button" className="button button-quiet" onClick={() => setRevising(false)}>Cancel</button></div></form>}
    <div className="decision-bar"><div><p className="eyebrow">Human decision required</p><span>Approval binds to report version {latest.version}. Fixture research is not live market evidence.</span></div><div className="button-row"><button className="button" disabled={busy} onClick={() => setRevising(true)}>Request changes</button><button className="button" disabled={busy} onClick={() => void act({ type: "REFERENCE_REPORT_DECISION", channelId: channel.id, reportVersion: latest.version, decision: "REJECT_DIRECTION" }, "Reference direction rejected; its history was preserved.")}>Reject direction</button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "REFERENCE_REPORT_DECISION", channelId: channel.id, reportVersion: latest.version, decision: "APPROVE" }, `Reference report v${latest.version} approved; original channel strategy created.`)}>Approve exact version <Check size={15} /></button></div></div>
    <div className="mode-switches"><button className="button button-quiet" disabled={busy} onClick={() => void act({ type: "REFERENCE_REPORT_DECISION", channelId: channel.id, reportVersion: latest.version, decision: "SWITCH_TO_DISCOVERY" }, "Reference direction rejected; opportunity discovery started.")}>Switch to opportunity discovery</button><details><summary>Switch to my own concept</summary><form onSubmit={switchToConcept}><label>Concept<textarea name="concept" required minLength={10} rows={3} /></label><label>Niche<input name="niche" required minLength={2} defaultValue={channel.preferences.niche} /></label><button className="button" disabled={busy}>Evaluate my concept</button></form></details></div>
  </section>;
}

function CandidateList({ title, items }: { title: string; items: Array<{ name: string; promise: string; complexity: string }> }) {
  return <section><h3>{title}</h3>{items.map((item) => <article key={item.name}><span>{item.complexity}</span><strong>{item.name}</strong><p>{item.promise}</p></article>)}</section>;
}

function ChannelOverview({ channel }: { channel: Channel }) {
  const current = channel.concepts.at(-1); const stage = channel.state === "READY_FOR_VIDEO_PRODUCTION" ? 5 : channel.state === "CONCEPT_SELECTION_REQUIRED" ? 2 : channel.state === "CONCEPT_REVIEW_REQUIRED" ? 3 : 1;
  return <section className="overview-card"><div className="overview-top"><div><p className="eyebrow">Active channel / {channel.mode.replace("_", " ")}</p><h2>{channel.preferences.name}</h2><p>{current?.concept ?? "Concept discovery in progress"}</p><TargetSummary targets={channel.preferences.distributionTargets} /></div><span className={`state-badge state-${channel.state.toLowerCase()}`}>{channel.state.replaceAll("_", " ")}</span></div><div className="stage-rail">{channelStages.map((item, index) => <div className={index < stage ? "done" : index === stage ? "current" : ""} key={item}><i>{index < stage ? <Check size={11} /> : index + 1}</i><span>{item}</span></div>)}</div></section>;
}

function TargetSummary({ targets }: { targets: Channel["preferences"]["distributionTargets"] }) {
  return <div className="target-summary" aria-label="Distribution targets"><span><Check size={11} /> YouTube</span>{targets.tiktok && <span><Check size={11} /> TikTok</span>}{targets.instagramFacebookReels && <span><Check size={11} /> Instagram/Facebook Reels</span>}</div>;
}

function ViabilityReview({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const version = channel.concepts.at(-1)!; const report = version.viability!; const [revising, setRevising] = useState(false);
  const revise = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); void act({ type: "REVISE_CONCEPT", channelId: channel.id, concept: String(form.get("concept")), niche: String(form.get("niche")), feedback: "Revised after viability review" }, "A new concept version was created and evaluated."); };
  return <section className="review-panel"><header><div><p className="eyebrow">Channel concept review / Version {version.version}</p><h2>Research suggests a <em>{report.recommendation.replace("_", " ")}</em> decision.</h2></div><div className={`recommendation recommendation-${report.recommendation.toLowerCase()}`}><span>{report.recommendation === "GO" ? <Check /> : <AlertTriangle />}</span><strong>{report.overallScore}</strong><small>/100<br />OVERALL</small></div></header>
    <p className="advisory">{report.summary}</p><div className="gate-grid">{Object.entries(report.gates).map(([name, gate]) => <article key={name}><div><span>{name.replace(/([A-Z])/g, " $1")}</span><b>{gate.status}</b></div><strong>{gate.score}</strong><p>{gate.evidence[0]}</p></article>)}</div>
    <div className="review-columns"><div><h3>Score breakdown</h3>{Object.entries(report.scores).map(([name, value]) => <div className="score-row" key={name}><span>{scoreLabels[name]}</span><i><b style={{ width: `${value}%` }} /></i><strong>{value}</strong></div>)}</div><div className="finding-box"><h3>What needs attention</h3>{report.risks.map((risk) => <p key={risk}><AlertTriangle size={14} /> {risk}</p>)}<h3>Repair direction</h3>{report.recommendedChanges.map((change) => <p key={change}><ChevronRight size={14} /> {change}</p>)}</div></div>
    {revising ? <form className="revision-form" onSubmit={revise}><h3>Create concept version {version.version + 1}</h3><label>Revised concept<textarea name="concept" required minLength={10} defaultValue={report.revisedConceptExamples[0] ?? version.concept} /></label><label>Niche<input name="niche" defaultValue={version.niche} /></label><div className="button-row"><button className="button button-accent" disabled={busy}>Evaluate revision <RefreshCcw size={15} /></button><button className="button button-quiet" type="button" onClick={() => setRevising(false)}>Cancel</button></div></form> : <div className="decision-bar"><div><p className="eyebrow">Human decision required</p><span>The system recommendation remains unchanged in history.</span></div><div className="button-row"><button className="button" disabled={busy} onClick={() => void act({ type: "CONCEPT_DECISION", channelId: channel.id, decision: "OVERRIDE_AND_CONTINUE" }, "Override recorded separately; channel strategy created.")}>Continue anyway</button><button className="button" disabled={busy} onClick={() => setRevising(true)}>Revise concept</button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "CONCEPT_DECISION", channelId: channel.id, decision: "REQUEST_ALTERNATIVES" }, "Alternative concepts are ready for selection.")}>Find better concepts <Sparkles size={15} /></button></div></div>}
  </section>;
}

function ConceptSelection({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  return <section className="selection-panel"><div className="panel-kicker"><span>02</span><div><p className="eyebrow">Opportunity shortlist</p><h2>Choose the thesis worth building</h2></div></div><p className="panel-lede">These are distinct fixture-backed directions, ranked by the same five viability gates. Selection remains human.</p><div className="candidate-grid">{channel.candidates.map((candidate, index) => <article key={candidate.id}><div className="candidate-number">0{index + 1}</div><span className={`mini-rec mini-${candidate.viability.recommendation.toLowerCase()}`}>{candidate.viability.recommendation}</span><h3>{candidate.concept}</h3><p>{candidate.promise}</p><div className="candidate-score"><strong>{candidate.viability.overallScore}</strong><span>/100<br />VIABILITY</span></div><div className="candidate-gates">{Object.entries(candidate.viability.gates).map(([name, gate]) => <span key={name}>{name.replace(/([A-Z])/g, " $1")} <b>{gate.status}</b></span>)}</div><button className="button button-wide" disabled={busy} onClick={() => void act({ type: "SELECT_CONCEPT", channelId: channel.id, candidateId: candidate.id }, "Concept selected and channel strategy persisted.")}>Select this concept <ArrowRight size={15} /></button></article>)}</div></section>;
}

function BusinessStrategyReview({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const current = channel.businessStrategies.at(-1)!;
  const strategy = current.strategy;
  const [feedback, setFeedback] = useState("");
  const journey = Object.entries(strategy.connectedJourney);
  return <section className="business-strategy-review"><header><div><p className="eyebrow">Three fundamentals / Strategy v{current.version}</p><h2>Connect attention to useful outcomes.</h2><p>The Pillar Video, free resource, and paid product are one customer journey. Pricing and demand remain fixture hypotheses until validated.</p></div><div className="strategy-verdict"><span>{strategy.fixture ? "FIXTURE" : "LIVE"}</span><strong>{current.qa.verdict}</strong><small>INDEPENDENT QA</small></div></header>
    <div className="journey-rail" aria-label="Connected customer journey">{journey.map(([stage, description], index) => <article key={stage}><span>{index + 1}</span><strong>{stage.replace(/([A-Z])/g, " $1")}</strong><p>{description}</p></article>)}</div>
    <div className="fundamentals-grid"><article className="pillar-plan"><p className="eyebrow">Pillar Video</p><h3>{strategy.pillarVideo.title}</h3><strong>{strategy.pillarVideo.highValuePromise}</strong><p>{strategy.pillarVideo.originalThesis}</p><ul>{strategy.pillarVideo.narrativeStructure.map((item) => <li key={item}>{item}</li>)}</ul><small>Connects to resource: {strategy.pillarVideo.freeResourceConnection}</small></article><article className="brand-board"><p className="eyebrow">Original brand system</p><h3>{strategy.brandSystem.name}</h3><div className="color-chips">{strategy.brandSystem.colors.map((color) => <span style={{ background: color.hex }} title={`${color.name}: ${color.use}`} key={color.name} />)}</div><p>{strategy.brandSystem.voice.join(" · ")}</p>{strategy.brandSystem.originalityNotes.map((item) => <small key={item}><ShieldCheck size={12} />{item}</small>)}</article></div>
    <div className="offer-review-grid"><StrategyOptions title="Free-resource options" items={strategy.freeResourceOptions.map((item) => ({ id: item.id, name: item.name, promise: item.promise, format: item.format, complexity: item.buildComplexity }))} /><StrategyOptions title="Paid-product options" items={strategy.paidProductOptions.map((item) => ({ id: item.id, name: item.name, promise: item.transformation, format: item.format, complexity: item.buildComplexity }))} /></div>
    <section className="monetization-preview"><p className="eyebrow">Broader monetization</p>{strategy.monetizationOverview.map((item) => <article key={item.stream}><span>0{item.priority}</span><strong>{item.stream}</strong><b>{item.fit} FIT</b><p>{item.timing}</p></article>)}</section>
    <div className="strategy-revision"><label>Revision feedback<textarea rows={3} maxLength={4000} value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="State what should change. A new version will be created." /></label><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "BUSINESS_STRATEGY_DECISION", channelId: channel.id, strategyVersion: current.version, decision: "REQUEST_CHANGES", feedback }, `Business strategy v${current.version + 1} created and reviewed.`)}>Request changes <RefreshCcw size={15} /></button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "BUSINESS_STRATEGY_DECISION", channelId: channel.id, strategyVersion: current.version, decision: "APPROVE" }, `Business strategy v${current.version} approved; video and offer selection unlocked.`)}>Approve exact strategy <Check size={15} /></button></div></div>
  </section>;
}

function StrategyOptions({ title, items }: { title: string; items: Array<{ id: string; name: string; promise: string; format: string; complexity: string }> }) {
  return <section><h3>{title}</h3>{items.map((item) => <article key={item.id}><span>{item.complexity}</span><strong>{item.name}</strong><p>{item.promise}</p><small>{item.format}</small></article>)}</section>;
}

function MonetizationReview({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const current = channel.monetizationPlans.at(-1)!;
  const [feedback, setFeedback] = useState("");
  const ranked = [...current.plan.streams].sort((a, b) => a.priority - b.priority);
  return <section id="monetization" className="monetization-review"><header><div><p className="eyebrow">Monetization Plan / Version {current.version}</p><h2>A ranked revenue portfolio, not a revenue promise.</h2><p>{current.plan.executiveSummary}</p></div><div className="strategy-verdict"><span>{current.plan.fixture ? "FIXTURE EVIDENCE" : "LIVE EVIDENCE"}</span><strong>{current.qa.verdict}</strong><small>INDEPENDENT QA</small></div></header>
    <div className="evidence-warning"><AlertTriangle size={18} /><p><strong>Unknowns remain explicit.</strong>{current.plan.unknowns.join(" ")}</p></div>
    <div className="monetization-ledger">{ranked.map((item) => <article key={item.stream}><header><span>#{String(item.priority).padStart(2, "0")}</span><div><h3>{item.stream.replaceAll("_", " ")}</h3><p>{item.channelFit} FIT · {item.recommendedTiming}</p></div><b>{item.timeToFirstRevenue}</b></header><div className="monetization-facts"><section><small>VERIFIED FACTS</small>{item.verifiedFacts.map((fact) => <p key={fact}><Check size={11} />{fact}</p>)}</section><section><small>ASSUMPTIONS / ESTIMATES</small>{item.assumptionsAndEstimates.map((assumption) => <p key={assumption}><FlaskConical size={11} />{assumption}</p>)}</section></div><footer><span>SETUP {item.setupEffort}</span><span>ONGOING {item.ongoingEffort}</span><span>{item.marginCharacteristics}</span></footer><details><summary>Dependencies, risks, actions, and metrics</summary><div className="monetization-detail"><section><strong>Eligibility and integrations</strong>{[...item.eligibilityDependencies, ...item.requiredIntegrations].map((value) => <p key={value}>{value}</p>)}</section><section><strong>Risks</strong>{item.reputationAndPlatformRisk.map((value) => <p key={value}>{value}</p>)}</section><section><strong>Next actions and measures</strong>{[...item.nextActions, ...item.metrics].map((value) => <p key={value}>{value}</p>)}</section></div></details></article>)}</div>
    <div className="strategy-revision"><label>Plan revision feedback<textarea rows={4} maxLength={4000} value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="Challenge assumptions, reprioritize streams, or request stronger risk analysis. A new version will be created." /></label><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "MONETIZATION_PLAN_DECISION", channelId: channel.id, planVersion: current.version, decision: "REQUEST_CHANGES", feedback }, `Monetization plan v${current.version + 1} created and reviewed.`)}>Request changes <RefreshCcw size={15} /></button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "MONETIZATION_PLAN_DECISION", channelId: channel.id, planVersion: current.version, decision: "APPROVE" }, `Monetization plan v${current.version} approved.`)}>Approve exact plan <Check size={15} /></button></div></div>
  </section>;
}

function ReadyWorkspace({ channel, video, build, media, busy, act }: { channel: Channel; video?: VideoProject; build?: BuildProject; media: MediaProductionSnapshot; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  if (build) return <BuildWorkspace project={build} busy={busy} act={act} />;
  if (video) return <><VideoReview video={video} busy={busy} act={act} /><MediaProductionPanel video={video} media={media} busy={busy} act={act} /><MediaHumanQaPanel video={video} media={media} busy={busy} act={act} /></>;
  const selectedConcept = channel.concepts.find((item) => item.id === channel.selectedConceptVersionId) ?? channel.concepts.at(-1);
  const viability = selectedConcept?.viability;
  const create = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); void act({ type: "CREATE_VIDEO", channelId: channel.id, topic: String(form.get("topic")) }, "Video strategy, research, script, and QA completed; human review is required."); };
  return <><ApprovedBusinessStrategy channel={channel} busy={busy} act={act} /><section className="strategy-panel"><div><p className="eyebrow">Persisted channel strategy</p><h2>{channel.strategy?.channelPromise}</h2><p>{channel.strategy?.positioning}</p></div><div className="strategy-grid"><article><h3>Content pillars</h3>{channel.strategy?.contentPillars.map((item) => <span key={item}>{item}</span>)}</article><article><h3>Recurring series</h3>{channel.strategy?.recurringSeries.map((item) => <span key={item}>{item}</span>)}</article><article><h3>Monetization</h3>{channel.strategy?.monetizationApproaches.map((item) => <span key={item}>{item}</span>)}</article></div>{viability && <section className="accepted-evidence"><header><div><p className="eyebrow">Accepted concept evidence / Version {selectedConcept?.version}</p><h3>{viability.recommendation.replaceAll("_", " ")} recommendation retained</h3></div><strong>{viability.overallScore}<small>/100</small></strong></header><p>{selectedConcept?.research?.summary ?? viability.summary}</p><div>{Object.entries(viability.gates).map(([name, gate]) => <span key={name}>{name.replace(/([A-Z])/g, " $1")}<b>{gate.status} · {gate.score}</b></span>)}</div></section>}</section><section className="video-launch"><div><p className="eyebrow">Standard video</p><h2>Develop another video</h2><p>The deterministic runner will create strategy, source-linked fixture research, a versioned script, and independent QA before pausing.</p><div className="launch-targets"><small>INHERITED TARGETS</small><TargetSummary targets={channel.preferences.distributionTargets} /></div></div><form onSubmit={create}><label>Video topic<input name="topic" required minLength={5} defaultValue="Why loyalty programs change the way customers make decisions" /></label><button className="button button-accent" disabled={busy}>Run to script review <ArrowRight size={16} /></button></form></section></>;
}

function ApprovedBusinessStrategy({ channel, busy, act }: { channel: Channel; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const approved = channel.businessStrategies.findLast((item) => item.status === "APPROVED")!;
  const freeSelection = channel.offerSelections.find((item) => item.strategyVersion === approved.version && item.offerType === "FREE_RESOURCE");
  const paidSelection = channel.offerSelections.find((item) => item.strategyVersion === approved.version && item.offerType === "PAID_PRODUCT");
  return <section className="approved-business"><header><div><p className="eyebrow">Approved business strategy / v{approved.version}</p><h2>{approved.strategy.pillarVideo.title}</h2></div><div className="button-row"><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "CREATE_PILLAR_VIDEO", channelId: channel.id, strategyVersion: approved.version }, "Pillar Video created and advanced to script review.")}>Create Pillar Video <Video size={15} /></button>{channel.monetizationPlans.length === 0 && <button className="button" disabled={busy} onClick={() => void act({ type: "GENERATE_MONETIZATION_PLAN", channelId: channel.id, strategyVersion: approved.version }, "Versioned monetization plan created and independently reviewed.")}>Plan monetization <Sparkles size={15} /></button>}{freeSelection && <button className="button" disabled={busy} onClick={() => void act({ type: "CREATE_RESOURCE_BUILD", channelId: channel.id, strategyVersion: approved.version }, "Versioned resource and funnel specification created for review.")}>Build selected resource <ArrowRight size={15} /></button>}{paidSelection && <button className="button" disabled={busy} onClick={() => void act({ type: "CREATE_PRODUCT_BUILD", channelId: channel.id, strategyVersion: approved.version }, "Versioned paid-product specification created for review.")}>Build selected product <ArrowRight size={15} /></button>}</div></header><div className="approved-offers"><OfferSelector title="Select the free resource" items={approved.strategy.freeResourceOptions.map((item) => ({ id: item.id, name: item.name, detail: item.promise }))} selectedId={freeSelection?.candidateId} disabled={busy} onSelect={(candidateId) => void act({ type: "SELECT_STRATEGY_OFFER", channelId: channel.id, strategyVersion: approved.version, offerType: "FREE_RESOURCE", candidateId }, "Free resource selected from the approved strategy version.")} /><OfferSelector title="Select the paid product" items={approved.strategy.paidProductOptions.map((item) => ({ id: item.id, name: item.name, detail: item.transformation }))} selectedId={paidSelection?.candidateId} disabled={busy} onSelect={(candidateId) => void act({ type: "SELECT_STRATEGY_OFFER", channelId: channel.id, strategyVersion: approved.version, offerType: "PAID_PRODUCT", candidateId }, "Paid product selected from the approved strategy version.")} /></div></section>;
}

function OfferSelector({ title, items, selectedId, disabled, onSelect }: { title: string; items: Array<{ id: string; name: string; detail: string }>; selectedId?: string; disabled: boolean; onSelect: (id: string) => void }) {
  return <section><h3>{title}</h3>{items.map((item) => <button type="button" className={selectedId === item.id ? "selected" : ""} disabled={disabled || Boolean(selectedId)} onClick={() => onSelect(item.id)} key={item.id}><span>{selectedId === item.id ? <Check size={13} /> : <CircleDot size={13} />}</span><strong>{item.name}</strong><small>{item.detail}</small></button>)}</section>;
}

function BuildWorkspace({ project, busy, act }: { project: BuildProject; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const specification = project.specifications.at(-1)!;
  const artifact = project.artifacts.at(-1);
  const [feedback, setFeedback] = useState("");
  const [email, setEmail] = useState("");
  if (project.state === "SPEC_REVIEW") return <section className="build-workspace"><header><div><p className="eyebrow">Product Builder / Specification v{specification.version}</p><h2>{specification.specification.name}</h2><p>{specification.specification.promise}</p></div><span className="build-state">SPEC REVIEW</span></header><div className="build-spec-grid"><article><h3>Frontend</h3>{specification.specification.frontend.map((item) => <p key={item}>{item}</p>)}</article><article><h3>Backend and data</h3>{[...specification.specification.backend, ...specification.specification.database].map((item) => <p key={item}>{item}</p>)}</article><article><h3>Constrained build</h3>{specification.specification.securityControls.map((item) => <p key={item}><ShieldCheck size={12} />{item}</p>)}</article></div><div className="blocker-box"><AlertTriangle size={17} /><p><strong>Deployment blockers</strong>{specification.specification.deploymentBlockers.join(" ")}</p></div><div className="strategy-revision"><label>Specification changes<textarea rows={3} value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="Request a new specification version" /></label><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "BUILD_SPEC_DECISION", buildProjectId: project.id, specificationVersion: specification.version, decision: "REQUEST_CHANGES", feedback }, `Build specification v${specification.version + 1} created.`)}>Request changes</button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "BUILD_SPEC_DECISION", buildProjectId: project.id, specificationVersion: specification.version, decision: "APPROVE" }, "Constrained fixture build completed; independent QA and user review are ready.")}>Approve spec and build</button></div></div></section>;
  if (!artifact) return <section className="build-workspace"><p>Build output is not available. Review the activity ledger and retry from the current state.</p></section>;
  if (project.projectType === "PAID_PRODUCT") return <PaidProductBuildArtifact project={project} busy={busy} act={act} feedback={feedback} setFeedback={setFeedback} />;
  const capture = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); void act({ type: "CAPTURE_FIXTURE_SUBSCRIBER", buildProjectId: project.id, email, consent: true, source: `fixture-preview-v${artifact.version}` }, "Fixture signup recorded. No live email was sent."); };
  return <section className="build-workspace"><header><div><p className="eyebrow">Resource and funnel artifact / v{artifact.version}</p><h2>{artifact.artifact.resourcePreview.title}</h2><p>{artifact.qa.summary}</p></div><span className={`build-state state-${project.state.toLowerCase()}`}>{project.state.replaceAll("_", " ")}</span></header><div className="build-evidence">{Object.entries(artifact.artifact.executionEvidence).map(([name, result]) => <span key={name}>{result === "PASSED" ? <Check size={12} /> : <AlertTriangle size={12} />}{name.replace(/([A-Z])/g, " $1")} <b>{result}</b></span>)}</div><div className="funnel-preview"><article><p className="eyebrow">Opt-in preview</p><h3>{artifact.artifact.pages.optIn.headline}</h3><p>{artifact.artifact.pages.optIn.body}</p><ul>{artifact.artifact.pages.optIn.benefits.map((item) => <li key={item}>{item}</li>)}</ul><form onSubmit={capture}><label>{artifact.artifact.pages.optIn.formLabel}<input type="email" required value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" /></label><label className="consent-preview"><input type="checkbox" required />{artifact.artifact.pages.optIn.consentLanguage}</label><button className="button button-accent" disabled={busy}>{artifact.artifact.pages.optIn.callToAction}</button><small>Fixture preview only. Records scoped consent and a fixture delivery event; sends no email.</small></form></article><article><p className="eyebrow">Thank-you preview</p><h3>{artifact.artifact.pages.thankYou.headline}</h3><p>{artifact.artifact.pages.thankYou.body}</p><button className="button" disabled>{artifact.artifact.pages.thankYou.callToAction}</button><small>No unrestricted asset URL exists in fixture mode.</small></article></div><details className="manifest"><summary>File manifest and QA</summary>{artifact.artifact.fileManifest.map((file) => <p key={file.path}><code>{file.path}</code><span>{file.kind} · {file.bytes} bytes</span></p>)}</details><div className="blocker-box"><AlertTriangle size={17} /><p><strong>Not deployable</strong>{artifact.artifact.deploymentBlockers.join(" ")}</p></div>{project.state === "USER_REVIEW" && <div className="strategy-revision"><label>Artifact changes<textarea rows={3} value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="Request a new artifact version" /></label><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: project.id, artifactVersion: artifact.version, decision: "REQUEST_CHANGES", feedback }, `Artifact v${artifact.version + 1} created and reviewed.`)}>Request changes</button>{project.artifacts.length > 1 && <button className="button" disabled={busy} onClick={() => void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: project.id, artifactVersion: 1, decision: "RESTORE_AS_NEW_VERSION" }, "Earlier artifact restored as a new version.")}>Restore v1 as new</button>}<button className="button button-accent" disabled={busy} onClick={() => void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: project.id, artifactVersion: artifact.version, decision: "APPROVE" }, "Artifact approved; deployment remains explicitly blocked.")}>Approve exact artifact</button></div></div>}</section>;
}

function PaidProductBuildArtifact({ project, busy, act, feedback, setFeedback }: { project: BuildProject; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void>; feedback: string; setFeedback: (value: string) => void }) {
  const artifact = project.artifacts.at(-1)!;
  const product = artifact.artifact.productPreview!;
  const commerce = artifact.artifact.commercePlan!;
  return <section className="build-workspace product-build"><header><div><p className="eyebrow">Paid-product artifact / v{artifact.version}</p><h2>{artifact.artifact.resourcePreview.title}</h2><p>{artifact.qa.summary}</p></div><span className={`build-state state-${project.state.toLowerCase()}`}>{project.state.replaceAll("_", " ")}</span></header><div className="product-preview"><article><p className="eyebrow">Transformation</p><h3>{product.transformation}</h3><h4>Minimum viable scope</h4>{product.minimumViableScope.map((item) => <p key={item}><Check size={13} />{item}</p>)}</article><article><p className="eyebrow">Verified commerce boundary</p>{commerce.checkout.map((item) => <p key={item}>{item}</p>)}<h4>Webhook and fulfillment</h4>{[...commerce.webhookVerification, ...commerce.fulfillment].map((item) => <p key={item}><ShieldCheck size={13} />{item}</p>)}<strong>ACCESS: {product.accessMode}</strong></article></div><div className="build-evidence">{Object.entries(artifact.artifact.executionEvidence).map(([name, result]) => <span key={name}><AlertTriangle size={12} />{name.replace(/([A-Z])/g, " $1")} <b>{result}</b></span>)}</div><div className="blocker-box"><AlertTriangle size={17} /><p><strong>Fixture only / not deployable</strong>{artifact.artifact.deploymentBlockers.join(" ")}</p></div>{project.state === "USER_REVIEW" && <div className="strategy-revision"><label>Product artifact changes<textarea rows={3} value={feedback} onChange={(event) => setFeedback(event.target.value)} /></label><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: project.id, artifactVersion: artifact.version, decision: "REQUEST_CHANGES", feedback }, `Paid-product artifact v${artifact.version + 1} created.`)}>Request changes</button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "BUILD_ARTIFACT_DECISION", buildProjectId: project.id, artifactVersion: artifact.version, decision: "APPROVE" }, "Paid-product artifact approved; deployment remains blocked.")}>Approve exact artifact</button></div></div>}{project.state === "DEPLOYMENT_BLOCKED" && <div className="fixture-commerce-action"><p><strong>Fixture commerce demonstration</strong>Activate a $99 pricing hypothesis for local checkout/webhook/entitlement testing. This does not create a live product or charge anyone.</p><button className="button" disabled={busy} onClick={() => void act({ type: "ACTIVATE_FIXTURE_PRODUCT", buildProjectId: project.id, artifactVersion: artifact.version, amountMinor: 9900, currency: "USD" }, "Fixture product and pricing hypothesis activated; no live checkout was created.")}>Activate fixture product</button></div>}</section>;
}

function VideoReview({ video, busy, act }: { video: VideoProject; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const script = video.scripts.at(-1)!; const [feedback, setFeedback] = useState("");
  return <section className="script-panel"><header><div><p className="eyebrow">Video project / Script v{script.version}</p><h2>{script.title}</h2><p>{video.topic}</p><TargetSummary targets={video.distributionTargets} /></div><span className={`state-badge state-${video.state.toLowerCase()}`}>{video.state.replaceAll("_", " ")}</span></header><div className="qa-strip"><FileCheck2 size={20} /><div><strong>Independent script QA: {video.qa?.verdict}</strong><span>{video.qa?.summary}</span></div>{video.qa && <b>{Math.round(Object.values(video.qa.scores).reduce((a, b) => a + b, 0) / 5)}/100</b>}</div><article className="script-document"><div className="script-hook"><span>HOOK</span><p>{script.hook}</p></div>{script.sections.map((section, index) => <section key={section.heading}><div><span>0{index + 1}</span><small>{section.estimatedSeconds}s</small></div><article><h3>{section.heading}</h3><em>{section.purpose}</em><p>{section.narration}</p>{section.claimRefs.length > 0 && <small>CLAIMS: {section.claimRefs.join(", ")}</small>}</article></section>)}</article>{video.state === "SCRIPT_APPROVED" ? <><div className="approved-panel"><ShieldCheck /><div><h3>Canonical script approved</h3><p>The durable approval references script version {script.version}. No master video or publishing package exists in this slice.</p></div></div><DistributionPackage video={video} busy={busy} act={act} /></> : <div className="script-decision"><div><p className="eyebrow">Human approval gate</p><h3>Does this version earn production?</h3></div><textarea aria-label="Revision feedback" value={feedback} onChange={(event) => setFeedback(event.target.value)} placeholder="Required only when requesting changes…" /><div className="button-row"><button className="button" disabled={busy || !feedback.trim()} onClick={() => void act({ type: "SCRIPT_DECISION", videoId: video.id, decision: "REQUEST_CHANGES", feedback }, "Feedback persisted; a new script version was created and reviewed.")}>Request changes <RefreshCcw size={15} /></button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "SCRIPT_DECISION", videoId: video.id, decision: "APPROVE" }, "Script approval persisted; selected fixture adaptation plans were generated.")}>Approve script <Check size={15} /></button></div></div>}</section>;
}

function MediaProductionPanel({ video, media, busy, act }: { video: VideoProject; media: MediaProductionSnapshot; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const script = video.scripts.at(-1)!;
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const inputIds = new Set(media.renderInputs.filter((input) => input.videoId === video.id).map((input) => input.id));
  const jobs = media.renderJobs.filter((job) => inputIds.has(job.renderInputId));
  const latestJob = jobs.at(-1);
  const latestMaster = media.masters.filter((master) => master.videoId === video.id).at(-1);
  const unresolvedAsset = media.assets.some((asset) => selectedAssets.includes(asset.id) && (asset.status !== "READY" || asset.rightsStatus !== "VERIFIED"));
  const canCancel = latestJob && ["QUEUED", "LEASED", "RETRY_WAIT"].includes(latestJob.status);
  const canRetry = latestJob && ["FAILED", "RETRY_WAIT"].includes(latestJob.status) && latestJob.attemptCount < latestJob.maxAttempts;
  const allQaPassed = latestMaster?.qaReports.length === 6 && latestMaster.qaReports.every((report) => report.verdict === "PASS");
  return <section className="media-production-panel"><header><div><p className="eyebrow">Media production ledger</p><h2>Stored and inspected master pipeline</h2></div><span>{media.evidence.replaceAll("_", " ")}</span></header><p className="media-boundary">A queued record is not a rendered video. A master appears here only after the isolated worker uploads the actual MP4, verifies its checksum, probes its streams, and atomically finalizes the exact version.</p><div className="asset-readiness"><h3>Asset readiness</h3>{media.assets.length === 0 ? <p>No stored assets selected. The render input will use application-generated visuals and remain silent.</p> : media.assets.map((asset) => <label key={asset.id}><input type="checkbox" checked={selectedAssets.includes(asset.id)} onChange={(event) => setSelectedAssets((current) => event.target.checked ? [...current, asset.id] : current.filter((id) => id !== asset.id))} /><span><strong>{asset.kind} · v{asset.version}</strong><small>{asset.provider} · {asset.mimeType} · {asset.rightsStatus}</small></span><b className={asset.status === "READY" && asset.rightsStatus === "VERIFIED" ? "ready" : "blocked"}>{asset.status === "READY" && asset.rightsStatus === "VERIFIED" ? "READY" : "BLOCKED"}</b></label>)}</div><div className="render-actions"><button className="button button-accent" disabled={busy || unresolvedAsset || Boolean(latestJob && ["QUEUED", "LEASED", "RETRY_WAIT"].includes(latestJob.status))} onClick={() => void act({ type: "CREATE_RENDER_JOB", videoId: video.id, scriptVersion: script.version, assetVersionIds: selectedAssets }, "Immutable render input created and job queued; no master is claimed yet.")}>Queue exact script v{script.version}</button>{canRetry && <button className="button" disabled={busy} onClick={() => void act({ type: "RETRY_RENDER_JOB", jobId: latestJob.id }, "Render job returned to the durable queue.")}><RefreshCcw size={14} /> Retry</button>}{canCancel && <button className="button" disabled={busy} onClick={() => void act({ type: "CANCEL_RENDER_JOB", jobId: latestJob.id }, "Render cancellation persisted.")}><XCircle size={14} /> Cancel</button>}</div>{latestJob && <article className="render-job-card"><header><strong>Render job</strong><b>{latestJob.status.replaceAll("_", " ")}</b></header><dl><div><dt>Attempts</dt><dd>{latestJob.attemptCount} / {latestJob.maxAttempts}</dd></div><div><dt>Lease</dt><dd>{latestJob.leasedBy ?? "unclaimed"}</dd></div><div><dt>Error</dt><dd>{latestJob.errorCode ?? "none"}</dd></div></dl></article>}{latestMaster ? <article className="master-card"><header><div><strong>Production master v{latestMaster.version}</strong><small>{latestMaster.checksumSha256.slice(0, 16)}… · {latestMaster.byteSize.toLocaleString()} bytes</small></div><b>{latestMaster.status.replaceAll("_", " ")}</b></header>{latestMaster.inspection && <dl><div><dt>Container / codecs</dt><dd>{latestMaster.inspection.container} · {latestMaster.inspection.videoCodec ?? "none"} / {latestMaster.inspection.audioCodec ?? "silent"}</dd></div><div><dt>Picture</dt><dd>{latestMaster.inspection.width}×{latestMaster.inspection.height} · {latestMaster.inspection.frameRate} fps · {latestMaster.inspection.pixelFormat}</dd></div><div><dt>Duration</dt><dd>{latestMaster.inspection.durationSeconds.toFixed(3)}s</dd></div><div><dt>Audio</dt><dd>{latestMaster.inspection.audioStreamCount ? `${latestMaster.inspection.integratedLoudnessLufs ?? "unknown"} LUFS · ${latestMaster.inspection.truePeakDbfs ?? "unknown"} dBFS` : "No audio stream"}</dd></div></dl>}<div className="qa-gates">{latestMaster.qaReports.map((report) => <span key={report.id} className={report.verdict === "PASS" ? "pass" : "block"}>{report.category}<b>{report.verdict}</b></span>)}</div><button className="button button-accent" disabled={busy || !allQaPassed} onClick={() => void act({ type: "APPROVE_PRODUCTION_MASTER", masterId: latestMaster.id, masterVersion: latestMaster.version }, `Production master v${latestMaster.version} approved for export.`)}>Approve exact master</button>{!allQaPassed && <p className="master-blocker"><AlertTriangle size={14} /> Unknown, blocked, failed, or unperformed QA categories prevent export readiness.</p>}</article> : <p className="no-master">No production master exists for this video.</p>}</section>;
}

function MediaHumanQaPanel({ video, media, busy, act }: { video: VideoProject; media: MediaProductionSnapshot; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const master = media.masters.filter((item) => item.videoId === video.id).at(-1);
  const [category, setCategory] = useState<"RIGHTS" | "CONTENT" | "VISUAL" | "AUDIO" | "PLATFORM">("CONTENT");
  const [verdict, setVerdict] = useState<"PASS" | "FAIL" | "BLOCKED">("PASS");
  const [finding, setFinding] = useState("");
  if (!master) return null;
  return <section className="human-qa-panel"><p className="eyebrow">Exact master v{master.version}</p><h3>Record a human QA decision</h3><p>Technical measurements cannot decide claims, rights, visual quality, subjective audio quality, or platform fit. Record only a review actually performed against this exact master.</p><div><label>Category<select value={category} onChange={(event) => setCategory(event.target.value as typeof category)}><option>RIGHTS</option><option>CONTENT</option><option>VISUAL</option><option>AUDIO</option><option>PLATFORM</option></select></label><label>Verdict<select value={verdict} onChange={(event) => setVerdict(event.target.value as typeof verdict)}><option>PASS</option><option>FAIL</option><option>BLOCKED</option></select></label></div><label>Finding<textarea rows={3} maxLength={2000} value={finding} onChange={(event) => setFinding(event.target.value)} placeholder="Describe what was reviewed and the evidence for this verdict." /></label><button className="button" disabled={busy || finding.trim().length < 3} onClick={() => void act({ type: "RECORD_MASTER_QA", masterId: master.id, masterVersion: master.version, category, verdict, finding }, `${category} QA ${verdict.toLowerCase()} recorded for master v${master.version}.`)}>Record exact-version QA</button></section>;
}

function DistributionPackage({ video, busy, act }: { video: VideoProject; busy: boolean; act: (a: WorkflowAction, s: string) => Promise<void> }) {
  const latest = ["TIKTOK", "INSTAGRAM_FACEBOOK_REELS"].map((target) => video.platformArtifacts.filter((item) => item.target === target).at(-1)).filter(Boolean) as VideoProject["platformArtifacts"];
  return <section className="distribution-package"><header><div><p className="eyebrow">Distribution package</p><h2>Vertical adaptation plans</h2></div><span>FIXTURE / NO MEDIA</span></header><article className="youtube-package"><div><Video size={18} /><strong>YouTube</strong></div><b>CANONICAL SOURCE</b><p>Script v{video.scripts.at(-1)?.version} is approved. A stored production master appears only after rendering and all required QA; the YouTube publishing package is not implemented.</p></article>{latest.map((artifact) => {
    const item = artifact.package; const revisionFeedback = `Revise ${artifact.target === "TIKTOK" ? "TikTok" : "Reels"} plan v${artifact.version}`;
    return <article className="platform-package" key={artifact.id}><header><div><strong>{artifact.target === "TIKTOK" ? "TikTok" : "Instagram/Facebook Reels"}</strong><span>{artifact.kind.replaceAll("_", " ")} · v{artifact.version}</span></div><b className={`package-status package-${artifact.status.toLowerCase()}`}>{artifact.status.replaceAll("_", " ")}</b></header><dl><div><dt>Source</dt><dd>Script v{artifact.sourceScriptVersion} · Master {artifact.sourceMasterVersion ?? "not available"}</dd></div><div><dt>Output</dt><dd>{item ? `${item.aspectRatio} plan · ${item.targetDurationSeconds}s · ${item.fixture ? "fixture" : "live"}` : "Generation failed"}</dd></div><div><dt>QA</dt><dd>{artifact.qa?.verdict ?? "Not completed"} · {artifact.qa?.summary ?? artifact.failure}</dd></div></dl>{item && <div className="package-copy"><h3>{item.hook}</h3><p>{item.condensedNarration.join(" ")}</p><small>CLAIMS: {item.claimReferences.join(", ")}</small><div>{item.publicationBlockers.map((blocker) => <span key={blocker}><AlertTriangle size={12} /> {blocker}</span>)}</div></div>}{artifact.status === "REVIEW_REQUIRED" && <div className="package-actions"><button className="button" disabled={busy} onClick={() => void act({ type: "PLATFORM_ARTIFACT_DECISION", videoId: video.id, target: artifact.target, artifactVersion: artifact.version, decision: "REQUEST_CHANGES", feedback: revisionFeedback }, "Feedback recorded; a new platform plan version was generated and reviewed.")}>Request changes <RefreshCcw size={14} /></button><button className="button button-accent" disabled={busy} onClick={() => void act({ type: "PLATFORM_ARTIFACT_DECISION", videoId: video.id, target: artifact.target, artifactVersion: artifact.version, decision: "APPROVE" }, "Exact platform plan version approved; media production remains blocked.")}>Approve plan <Check size={14} /></button></div>}</article>;
  })}{latest.length === 0 && <p className="youtube-only-note">No optional platform was selected for this video snapshot.</p>}</section>;
}

function ActivityRail({ snapshot, channel }: { snapshot: ApiSnapshot; channel: Channel }) {
  const events = useMemo(() => snapshot.auditEvents.slice(-8).reverse(), [snapshot.auditEvents]);
  return <aside className="activity-rail"><section><div className="rail-title"><p className="eyebrow">System ledger</p><span>{snapshot.agentRuns.length} RUNS</span></div><div className="metric-pair"><article><strong>${snapshot.agentRuns.reduce((sum, item) => sum + item.costUsd, 0).toFixed(2)}</strong><span>FIXTURE COST</span></article><article><strong>{channel.concepts.length}</strong><span>CONCEPT VERSIONS</span></article></div></section><section><div className="rail-title"><p className="eyebrow">Recent events</p><Clock3 size={14} /></div><div className="event-list">{events.map((event) => <div key={event.id}><i /><p>{event.type.replaceAll("_", " ")}<span>{new Date(event.at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></p></div>)}</div></section><section className="boundary-note"><Search size={18} /><h3>Fixture boundary</h3><p>No live competitor, trend, or demand claims are made. Current provider research is required before publishing or spending.</p></section></aside>;
}
